#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("session required");auto graph=loadGraph(argv[1]);size_t count=0;for(size_t n=0;n<graph.elements.size();++n){auto&e=graph.elements[n];if(graph.strings.at(e.type)!="DmeCamera")continue;++count;std::cout<<"camera="<<n<<" name="<<graph.strings.at(e.name)<<'\n';for(auto&a:e.attributes){std::cout<<"  "<<graph.strings.at(a.name)<<" type="<<unsigned(a.type)<<" count="<<a.values.size();if(a.values.size()==1){auto&v=a.values[0];if(a.type==1)std::cout<<" ref="<<v.reference;else if(a.type==3)std::cout<<" float="<<wireFloat(v);else if(a.type==2)std::cout<<" int="<<wireInt(v);else if(a.type==5)std::cout<<" text="<<v.text;}std::cout<<'\n';}}std::cout<<"session_cameras="<<count<<" graph_modified=no\n";if(!count)throw std::runtime_error("no camera fixtures");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
